import React from 'react';
import './CaseVisual.css';

const THEMES = {
  rifle: { match: 'rifle arsenal', title: 'RIFLE ARSENAL', icon: 'AK', accent: '#b63b4f', accent2: '#ef7185', glow: 'rgba(182,59,79,.30)' },
  knife: { match: 'knife arsenal', title: 'KNIFE ARSENAL', icon: '✦', accent: '#b98a2f', accent2: '#f3c86a', glow: 'rgba(185,138,47,.28)' },
  gloves: { match: 'gloves arsenal', title: 'GLOVES ARSENAL', icon: '✋', accent: '#3a78a2', accent2: '#79b7de', glow: 'rgba(58,120,162,.28)' },
};

function themeFor(name='') {
  const value = String(name).toLowerCase();
  if (value.includes('rifle arsenal')) return THEMES.rifle;
  if (value.includes('knife arsenal') || value.includes('knives arsenal')) return THEMES.knife;
  if (value.includes('gloves arsenal') || value.includes('glove arsenal')) return THEMES.gloves;
  return null;
}

export function isArsenalCase(name='') { return !!themeFor(name); }

export default function CaseVisual({ caseData, large=false, splash=false }) {
  const theme = themeFor(caseData?.name);
  if (!theme) return null;
  return (
    <div
      className={`case-visual ${large ? 'case-visual-large' : ''} ${splash ? 'case-visual-splash' : ''}`}
      style={{ '--cv-accent': theme.accent, '--cv-accent2': theme.accent2, '--cv-glow': theme.glow }}
      aria-label={caseData?.name || theme.title}
    >
      <div className="cv-stars" />
      <div className="cv-halo" />
      <div className="cv-floor" />
      <div className="cv-crate">
        <div className="cv-lid" />
        <div className="cv-body">
          <div className="cv-corner cv-corner-tl" /><div className="cv-corner cv-corner-tr" />
          <div className="cv-corner cv-corner-bl" /><div className="cv-corner cv-corner-br" />
          <div className="cv-panel"><b>{theme.icon}</b><span>WELLCASE</span><em>{theme.title}</em></div>
          <div className="cv-lock cv-lock-left" /><div className="cv-lock cv-lock-right" />
          <div className="cv-rail cv-rail-left" /><div className="cv-rail cv-rail-right" />
        </div>
      </div>
      <div className="cv-caption">{theme.title}</div>
    </div>
  );
}
